package com.example.vr.audio\n\nimport android.content.Context\nimport android.util.Log\nimport kotlinx.coroutines.*\nimport java.io.File\nimport java.util.concurrent.ConcurrentHashMap\n\n/**\n * ProcessedAudioManager\n *\n * Manages caching and offline preprocessing of audio tracks.\n * Ensures each video is processed only once; subsequent calls return cached result.\n */\nclass ProcessedAudioManager(private val context: Context) {\n    companion object {\n        private const val TAG = \"ProcessedAudioManager\"\n        private const val CACHE_DIR = \"audio_processing_cache\"\n    }\n\n    private val pipeline = AudioProcessingPipeline()\n    private val processingJobs = ConcurrentHashMap<String, Job>()\n    private val modelsInitialized = AtomicReference<Boolean>(false)\n\n    /**\n     * Get processed audio path (cached if available, otherwise preprocess)\n     *\n     * @param videoUri Input video URI (or path)\n     * @return Path to processed audio file, or null if processing failed\n     */\n    suspend fun getProcessedAudio(\n        videoUri: String,\n        onProgress: (progress: Int) -> Unit = {}\n    ): String? = withContext(Dispatchers.Default) {\n        try {\n            val cacheFile = getCacheFile(videoUri)\n\n            // Return if already cached\n            if (cacheFile.exists()) {\n                Log.d(TAG, \"Using cached audio: ${cacheFile.path}\")\n                return@withContext cacheFile.path\n            }\n\n            // Check if already processing\n            val existingJob = processingJobs[videoUri]\n            if (existingJob != null) {\n                Log.d(TAG, \"Waiting for existing processing job: $videoUri\")\n                existingJob.join()\n                if (cacheFile.exists()) {\n                    return@withContext cacheFile.path\n                } else {\n                    return@withContext null\n                }\n            }\n\n            // Start new processing job\n            val job = launch(Dispatchers.Default) {\n                try {\n                    Log.i(TAG, \"Starting audio preprocessing: $videoUri\")\n\n                    // Initialize models once\n                    if (!modelsInitialized.get()) {\n                        Log.d(TAG, \"Initializing audio processing models...\")\n                        pipeline.initializeModels(getModelDir())\n                        modelsInitialized.set(true)\n                        onProgress(10)\n                    }\n\n                    // Process audio\n                    val duration = pipeline.processAudio(videoUri, cacheFile.path)\n                    Log.i(TAG, \"Preprocessing complete: ${cacheFile.path} (${duration}ms)\")\n                    onProgress(100)\n                } catch (e: CancellationException) {\n                    Log.w(TAG, \"Audio preprocessing cancelled\")\n                    cacheFile.delete()\n                } catch (e: Exception) {\n                    Log.e(TAG, \"Audio preprocessing failed\", e)\n                    cacheFile.delete()\n                    throw e\n                } finally {\n                    processingJobs.remove(videoUri)\n                }\n            }\n\n            processingJobs[videoUri] = job\n            job.join()\n\n            if (cacheFile.exists()) cacheFile.path else null\n        } catch (e: Exception) {\n            Log.e(TAG, \"Error in getProcessedAudio\", e)\n            null\n        }\n    }\n\n    /**\n     * Preprocess audio in background (fire-and-forget)\n     *\n     * Can be called when video is first opened; result is cached for immediate playback on next open.\n     */\n    fun preprocessAudioInBackground(videoUri: String) {\n        GlobalScope.launch(Dispatchers.Default) {\n            try {\n                getProcessedAudio(videoUri)\n            } catch (e: Exception) {\n                Log.w(TAG, \"Background preprocessing failed (non-fatal)\", e)\n            }\n        }\n    }\n\n    /**\n     * Cancel ongoing preprocessing\n     */\n    fun cancelProcessing(videoUri: String) {\n        val job = processingJobs[videoUri]\n        job?.cancel()\n    }\n\n    /**\n     * Clear all cached processed audio\n     */\n    fun clearCache() {\n        val cacheDir = File(context.cacheDir, CACHE_DIR)\n        if (cacheDir.exists()) {\n            cacheDir.deleteRecursively()\n            Log.i(TAG, \"Audio cache cleared\")\n        }\n    }\n\n    /**\n     * Get cache file path for a video URI\n     */\n    private fun getCacheFile(videoUri: String): File {\n        val cacheDir = File(context.cacheDir, CACHE_DIR)\n        cacheDir.mkdirs()\n        val hash = videoUri.hashCode().toString(16)\n        return File(cacheDir, \"audio_${hash}_processed.m4a\")\n    }\n\n    /**\n     * Get model directory (download if needed)\n     */\n    private fun getModelDir(): String {\n        val modelDir = File(context.cacheDir, \"audio_models\")\n        modelDir.mkdirs()\n        // TODO: Download models on first run\n        return modelDir.path\n    }\n}\n"